pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Writer w;
    Checker k;
    function setUp() public { c = new C(); w = new Writer(); k = new Checker(); }

    function testFuzz_property(uint256 v) public {
        vm.assume(v != 0);
        // In the reference (plain call), the writer only touches its own storage;
        // C's slot 0 stays zero, so the checker callee succeeds. Under the
        // mutant (delegatecall), the writer stores v into C's slot 0, and the
        // checker callee then reverts, so forward fails.
        bool ok;
        try c.forward(address(w), abi.encode(v)) {
            try c.forward(address(k), "") { ok = true; } catch { ok = false; }
        } catch { ok = false; }
        assertTrue(ok);
    }
}

contract Writer {
    fallback() external {
        assembly { sstore(0, calldataload(4)) }
    }
}

contract Checker {
    fallback() external {
        assembly { if iszero(iszero(sload(0))) { revert(0, 0) } }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 x) public {
        // permissive adversarial counterparty: accepts any call
        OkCallee okC = new OkCallee();
        // calldata the fuzzer parameterizes (x); it targets a selector that
        // reverts when executed on the owner (this test contract)
        bytes memory data = abi.encodeWithSelector(this.trap.selector, x);
        bool ok;
        try c.forward(address(okC), data) {
            ok = true;
        } catch {
            ok = false;
        }
        // general rule: forwarding an accepted call to the requested callee always succeeds
        assertTrue(ok);
    }

    // any low-level call executing this selector on the owner reverts
    function trap(uint256) public pure {
        revert("trap");
    }
}

contract OkCallee {
    fallback() external payable {}
}

contract InvMutTest {

    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes calldata data) public {
        // Drive c's public surface: forward calls back into this contract,
        // whose fallback always rejects the call.
        bool ok;
        try c.forward(address(this), data) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: if the callee rejects the call, forward must revert.
        assert(!ok);
    }

    fallback() external {
        revert();
    }
}

